typedef enum {
    S2N_SNI_NONE = 1,
    S2N_SNI_EXACT_MATCH,
    S2N_SNI_WILDCARD_MATCH,
    S2N_SNI_NO_MATCH,
} s2n_cert_sni_match;

typedef enum {
    S2N_EARLY_DATA_STATUS_OK,
    S2N_EARLY_DATA_STATUS_NOT_REQUESTED,
    S2N_EARLY_DATA_STATUS_REJECTED,
    S2N_EARLY_DATA_STATUS_END,
} s2n_early_data_status_t;

typedef enum {
    S2N_ASYNC_OFFLOAD_PKEY_VERIFY = 0x01,
    /* Max value: ISO C restricts enumerator values to range of ‘int’ before C2X. */
    S2N_ASYNC_OFFLOAD_ALLOW_ALL = 0x7FFFFFFF,
} s2n_async_offload_op_type;

struct s2n_event_handshake {
    /**
     * The negotiated protocol version
     * 
     * This will be one of the protocol version constants defined in s2n.h 
     */
    int protocol_version;
    /* static memory */
    const char *cipher;
    /* static memory */
    const char *group;
    /* the amount of time inside the synchronous s2n_negotiate method */
    uint64_t handshake_time_ns;
    /**
     * The start of the handshake. This is not an interpretable time, and only has
     * meaning in reference to handshake_end_ns. 
     *
     * This is also used as a flag to ensure that the same event isn't emitted 
     * twice. After the event has been emitted this is set to HANDSHAKE_EVENT_SENT
     */
    uint64_t handshake_start_ns;
    uint64_t handshake_end_ns;
};

typedef enum {
    /* See https://engineering.salesforce.com/tls-fingerprinting-with-ja3-and-ja3s-247362855967 */
    S2N_FINGERPRINT_JA3,
    /* See https://github.com/FoxIO-LLC/ja4/tree/main */
    S2N_FINGERPRINT_JA4,
} s2n_fingerprint_type;

typedef enum {
    /* The client will take no action */
    S2N_RENEGOTIATE_IGNORE = 0,
    /* The client will send a warning alert to the server */
    S2N_RENEGOTIATE_REJECT,
    /* The client will begin renegotiation in the future */
    S2N_RENEGOTIATE_ACCEPT,
} s2n_renegotiate_response;

