// Call the API to obtain the thread-local s2n_errno pointer
int *errno_ptr = s2n_errno_location();
// Property: returned pointer must not be NULL when library is loaded
FUZZ_ASSERT(errno_ptr != nullptr, "s2n_errno_location returned NULL");
// Do not share across threads; we simply return it to the pool for potential same-thread use

// Use a valid s2n error code by reading the thread-local s2n_errno
int *errno_ptr = s2n_errno_location();
FUZZ_ASSERT(errno_ptr != nullptr, "s2n_errno_location returned NULL");
int err = *errno_ptr;
// Map to a high-level error type. We do not assert on return because any int is technically accepted,
// but we ensure we pass a realistic value from s2n_errno.
int type = s2n_error_get_type(err);
(void) type; // consume result

// Must be called before s2n_init(); enforce with a global attribute
int already_init = FUZZ_GET_ATTR_INT_GLOBAL("s2n_initialized");
if (already_init) { FUZZ_BAIL(); }
int r = s2n_crypto_disable_init();
(void) r; // may succeed or fail depending on build/runtime state

// Must be called before s2n_init(); enforce with a global attribute
int already_init = FUZZ_GET_ATTR_INT_GLOBAL("s2n_initialized");
if (already_init) { FUZZ_BAIL(); }
int r = s2n_disable_atexit();
(void) r; // return value may vary based on state

// No preconditions; just call and consume the version number
unsigned long v = s2n_get_openssl_version();
(void) v;

// Not thread-safe; should only be called once per process. Enforce via global attribute.
if (FUZZ_GET_ATTR_INT_GLOBAL("s2n_initialized")) { FUZZ_BAIL(); }
int r = s2n_init();
if (r != 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT_GLOBAL("s2n_initialized", 1);

// Cleans up thread-local resources; may be called multiple times.
int r = s2n_cleanup();
(void) r; // do not change global initialized flag here by design

// Perform complete deinitialization. After success, clear global initialized flag.
int r = s2n_cleanup_final();
if (r == 0) {
    FUZZ_SET_ATTR_INT_GLOBAL("s2n_initialized", 0);
}
(void) r;

// Provide a non-NULL output pointer to receive mode
s2n_fips_mode out_mode = S2N_FIPS_MODE_DISABLED;
int r = s2n_get_fips_mode(&out_mode);
(void) r;
(void) out_mode;

// Create a new config; caller must free later
struct s2n_config *config = s2n_config_new();
FUZZ_ASSERT(config != nullptr, "s2n_config_new returned NULL");
// Return the config so it persists for subsequent stubs

// Create a new minimal config; caller must free later
struct s2n_config *config = s2n_config_new_minimal();
FUZZ_ASSERT(config != nullptr, "s2n_config_new_minimal returned NULL");

// Free a config previously created by s2n_config_new/new_minimal
int r = s2n_config_free(config);
(void) r;
// Do not return config; it is no longer valid after free

// Free only the DH params on the config; config remains valid
int r = s2n_config_free_dhparams(config);
(void) r;
// Return the config so it stays in the pool

// Free only the cert chain and key on the config; config remains valid
int r = s2n_config_free_cert_chain_and_key(config);
(void) r;
// Return the config for continued use

// Use a realistic s2n error code from thread-local storage
int *errno_ptr = s2n_errno_location();
FUZZ_ASSERT(errno_ptr != nullptr, "s2n_errno_location returned NULL");
int err = *errno_ptr;
// Choose language: either NULL or "EN"
const char *lang = ( (*FUZZ_PARAM(unsigned int)) & 1 ) ? "EN" : nullptr;
const char *msg = s2n_strerror(err, lang);
(void) msg;

int *errno_ptr = s2n_errno_location();
FUZZ_ASSERT(errno_ptr != nullptr, "s2n_errno_location returned NULL");
int err = *errno_ptr;
const char *lang = ( (*FUZZ_PARAM(unsigned int)) & 1 ) ? "EN" : nullptr;
const char *msg = s2n_strerror_debug(err, lang);
(void) msg;

int *errno_ptr = s2n_errno_location();
FUZZ_ASSERT(errno_ptr != nullptr, "s2n_errno_location returned NULL");
int err = *errno_ptr;
const char *name = s2n_strerror_name(err);
(void) name;

int *errno_ptr = s2n_errno_location();
FUZZ_ASSERT(errno_ptr != nullptr, "s2n_errno_location returned NULL");
int err = *errno_ptr;
const char *src = s2n_strerror_source(err);
(void) src;

// Provide a non-capturing callback that returns a plausible timestamp in nanoseconds
// Do NOT use FUZZ_PARAM inside the lambda to avoid capture/compile issues.
s2n_clock_time_nanoseconds clock_fn = +[](void *ctx, uint64_t *ns_out) -> int {
    (void) ctx;
    if (ns_out == nullptr) return -1;
    // Use a function-static counter to produce deterministic, valid values
    static uint64_t counter = 0;
    counter += 1000; // advance by 1 microsecond per call
    *ns_out = counter;
    return 0;
};
// Optional context; keep NULL to avoid dangling references if invoked later
void *ctx = nullptr;
int r = s2n_config_set_wall_clock(config, clock_fn, ctx);
(void) r; // API may validate callback immediately or just store it
// Return config; it remains valid and now has a wall clock callback set

// Provide a monotonic clock callback that never moves backwards
s2n_clock_time_nanoseconds clock_fn = +[](void *ctx, uint64_t *ns_out) -> int {
    (void) ctx;
    if (ns_out == nullptr) return -1;
    // Monotonic non-decreasing counter
    static uint64_t mono = 0;
    mono += 500; // advance by 500ns per call
    *ns_out = mono;
    return 0;
};
void *ctx = nullptr;
int r = s2n_config_set_monotonic_clock(config, clock_fn, ctx);
(void) r;
// Return config; it remains valid with a monotonic clock configured

// Query whether stack traces are currently enabled
bool enabled = s2n_stack_traces_enabled();
(void) enabled;

// Toggle stack trace capture on or off using a fuzzed boolean
bool newval = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
int r = s2n_stack_traces_enabled_set(newval);
(void) r;

// Calculate the current stacktrace; only meaningful if enabled
int r = s2n_calculate_stacktrace();
(void) r;

// Print the current stacktrace to a writable FILE*
// Use a temporary file to satisfy the writable FILE* requirement
FILE *f = tmpfile();
if (!f) { FUZZ_BAIL(); }
int r = s2n_print_stacktrace(f);
(void) r;
// Close the file to avoid leaks
fclose(f);

// Free any memory used by the current stacktrace
int r = s2n_free_stacktrace();
(void) r;

// Register a store callback. Implement minimal contract: return success.
s2n_cache_store_callback store_cb = +[](struct s2n_connection *conn, void *data,
        uint64_t ttl_in_seconds, const void *key, uint64_t key_size,
        const void *value, uint64_t value_size) -> int {
    (void) conn; (void) data; (void) ttl_in_seconds; (void) key; (void) key_size; (void) value; (void) value_size;
    // Accept all inputs and report success; s2n makes a copy
    return 0;
};
void *ctx = nullptr;
int r = s2n_config_set_cache_store_callback(config, store_cb, ctx);
(void) r;
// Return config for continued use

// Register a retrieve callback. Implement contract regarding value_size and buffer sizing.
s2n_cache_retrieve_callback retrieve_cb = +[](struct s2n_connection *conn, void *data,
        const void *key, uint64_t key_size, void *value, uint64_t *value_size) -> int {
    (void) conn; (void) data; (void) key; (void) key_size;
    if (value_size == nullptr) return -1;
    // Minimal deterministic response: a single zero byte if buffer large enough
    const uint64_t needed = 1;
    if (value == nullptr || *value_size < needed) {
        *value_size = needed; // inform caller of required size
        return -1; // indicate insufficient space per contract
    }
    ((uint8_t *) value)[0] = 0;
    *value_size = needed;
    return 0;
};
void *ctx = nullptr;
int r = s2n_config_set_cache_retrieve_callback(config, retrieve_cb, ctx);
(void) r;

// Register a delete callback. Implement minimal success behavior.
s2n_cache_delete_callback delete_cb = +[](struct s2n_connection *conn, void *data,
        const void *key, uint64_t key_size) -> int {
    (void) conn; (void) data; (void) key; (void) key_size;
    return 0; // report success
};
void *ctx = nullptr;
int r = s2n_config_set_cache_delete_callback(config, delete_cb, ctx);
(void) r;

// Must be called before s2n_init(); enforce via global attribute
if (FUZZ_GET_ATTR_INT_GLOBAL("s2n_initialized")) { FUZZ_BAIL(); }
// Provide allocator callbacks that wrap malloc/free with the required contracts
s2n_mem_init_callback mem_init = +[]() -> int { return 0; };
s2n_mem_cleanup_callback mem_cleanup = +[]() -> int { return 0; };
s2n_mem_malloc_callback mem_malloc = +[](void **ptr, uint32_t requested, uint32_t *allocated) -> int {
    if (!ptr || !allocated) return -1;
    // Cap allocations to avoid large requests during fuzzing
    uint32_t req = requested;
    if (req > 2048u) req = 2048u;
    void *p = malloc(req ? req : 1u);
    if (!p) return -1;
    *ptr = p;
    *allocated = req;
    return 0;
};
s2n_mem_free_callback mem_free = +[](void *ptr, uint32_t size) -> int {
    (void) size; // size may be ignored by implementation
    if (ptr) free(ptr);
    return 0;
};
int r = s2n_mem_set_callbacks(mem_init, mem_cleanup, mem_malloc, mem_free);
(void) r;

// Must be called before s2n_init(); enforce via global attribute
if (FUZZ_GET_ATTR_INT_GLOBAL("s2n_initialized")) { FUZZ_BAIL(); }
// Provide RNG callbacks with minimal valid behavior (ignored in FIPS mode)
s2n_rand_init_callback rinit = +[]() -> int { return 0; };
s2n_rand_cleanup_callback rclean = +[]() -> int { return 0; };
s2n_rand_seed_callback rseed = +[](void *data, uint32_t size) -> int {
    (void) data; (void) size; return 0; // accept seed
};
s2n_rand_mix_callback rmix = +[](void *data, uint32_t size) -> int {
    (void) data; (void) size; return 0; // accept mix
};
int r = s2n_rand_set_callbacks(rinit, rclean, rseed, rmix);
(void) r;

// Allocate a new certificate chain and key handle
struct s2n_cert_chain_and_key *cert_and_key = s2n_cert_chain_and_key_new();
FUZZ_ASSERT(cert_and_key != nullptr, "s2n_cert_chain_and_key_new returned NULL");
// Return the handle for further operations

// Attempt to load PEM chain and key. Provide fuzzed PEM-like strings.
std::string chain_pem = FUZZ_PARAM_STR();
std::string key_pem = FUZZ_PARAM_STR();
// Ensure NUL-terminated C strings are passed as required by API
int r = s2n_cert_chain_and_key_load_pem(chain_and_key, chain_pem.c_str(), key_pem.c_str());
(void) r; // May fail if not valid PEM; acceptable in fuzzing
// Return the handle regardless of success for further exercises

// Attempt to load PEM from byte buffers; sizes are constrained to <= 2048
std::string chain_bytes = FUZZ_PARAM_STR();
std::string key_bytes = FUZZ_PARAM_STR();
uint32_t chain_len = (uint32_t)((chain_bytes.size() > 2048u) ? 2048u : chain_bytes.size());
uint32_t key_len = (uint32_t)((key_bytes.size() > 2048u) ? 2048u : key_bytes.size());
int r = s2n_cert_chain_and_key_load_pem_bytes(chain_and_key,
    (uint8_t *) chain_bytes.data(), chain_len,
    (uint8_t *) key_bytes.data(), key_len);
(void) r; // May fail if buffers are not valid PEM

// Attempt to load only a public certificate chain from bytes
std::string chain_bytes = FUZZ_PARAM_STR();
uint32_t chain_len = (uint32_t)((chain_bytes.size() > 2048u) ? 2048u : chain_bytes.size());
int r = s2n_cert_chain_and_key_load_public_pem_bytes(chain_and_key,
    (uint8_t *) chain_bytes.data(), chain_len);
(void) r; // May fail if not valid PEM

// Free the certificate chain and key handle
int r = s2n_cert_chain_and_key_free(cert_and_key);
(void) r; // Handle is invalid after this call; do not return it

// Attach an opaque user context pointer. We use a stable small integer casted to void*
void *ctx = (void *)(uintptr_t)(*FUZZ_PARAM(unsigned int));
int r = s2n_cert_chain_and_key_set_ctx(cert_and_key, ctx);
(void) r;
// Track the context for validation in get_ctx
FUZZ_SET_ATTR_PTR(cert_and_key, "ctx", ctx);

// Retrieve the previously set context pointer
void *got = s2n_cert_chain_and_key_get_ctx(cert_and_key);
// If we set a ctx attribute earlier, ensure it matches (property-based check)
void *expected = FUZZ_GET_ATTR_PTR(cert_and_key, "ctx");
if (expected != nullptr) {
    FUZZ_ASSERT(got == expected, "s2n_cert_chain_and_key_get_ctx mismatch");
}
(void) got;

// Enforce: the handle must have a private key loaded. We rely on an attribute set by a successful load call.
int has_key = FUZZ_GET_ATTR_INT(cert_and_key, "has_privkey");
if (!has_key) { FUZZ_BAIL(); }
// Retrieve the private key pointer managed by s2n-tls
s2n_cert_private_key *priv_key = s2n_cert_chain_and_key_get_private_key(cert_and_key);
FUZZ_ASSERT(priv_key != nullptr, "s2n_cert_chain_and_key_get_private_key returned NULL despite attribute");
// Outputs: return both the chain_and_key (still owned by caller) and the non-owning private key handle
// Validation: We checked precondition via attribute and assert non-NULL return.

// Provide OCSP stapling data; s2n copies the data
std::string ocsp = FUZZ_PARAM_STR();
uint32_t len = (uint32_t)((ocsp.size() > 2048u) ? 2048u : ocsp.size());
int r = s2n_cert_chain_and_key_set_ocsp_data(chain_and_key, (const uint8_t *) ocsp.data(), len);
(void) r;
// Validation: chain_and_key remains valid; data is copied by API.

// Provide SCT list bytes; s2n copies the data
std::string sct = FUZZ_PARAM_STR();
uint32_t len = (uint32_t)((sct.size() > 2048u) ? 2048u : sct.size());
int r = s2n_cert_chain_and_key_set_sct_list(chain_and_key, (const uint8_t *) sct.data(), len);
(void) r;
// Validation: chain_and_key remains valid; data is copied by API.

// Register a tie-break callback that deterministically prefers cert1 when name_len is even, else cert2.
s2n_cert_tiebreak_callback cb = +[](struct s2n_cert_chain_and_key *cert1, struct s2n_cert_chain_and_key *cert2,
        uint8_t *name, uint32_t name_len) -> struct s2n_cert_chain_and_key * {
    (void) name;
    if ((name_len & 1u) == 0u) { return cert1; }
    return cert2 ? cert2 : cert1; // if cert2 is NULL, fall back to cert1
};
int r = s2n_config_set_cert_tiebreak_callback(config, cb);
(void) r;
// Validation: callback is non-capturing and follows return contract; config remains valid.

// Deprecated API: add a single chain+key from PEM strings
std::string chain_pem = FUZZ_PARAM_STR();
std::string key_pem = FUZZ_PARAM_STR();
int r = s2n_config_add_cert_chain_and_key(config, chain_pem.c_str(), key_pem.c_str());
(void) r;
// Validation: config remains valid irrespective of success; strings are NUL-terminated.

// Preferred API: add an existing chain+key handle to the config's store
int r = s2n_config_add_cert_chain_and_key_to_store(config, cert_key_pair);
(void) r;
// Track association to avoid freeing while in use by config
FUZZ_SET_ATTR_INT(cert_key_pair, "in_config", 1);
// Validation: both objects remain owned externally; we return both to the pool.

// Build a one-element array of cert_key_pairs as required by the API
struct s2n_cert_chain_and_key *arr[1];
arr[0] = cert_key_pair;
uint32_t num = 1;
int r = s2n_config_set_cert_chain_and_key_defaults(config, arr, num);
(void) r;
// Validation: pointers form a valid array for num=1; we return both objects.

// Provide either a file or a directory. We prefer a file with random data; parser may fail which is acceptable.
const char *file = FUZZ_PARAM_FILENAME();
// Occasionally pass a directory-like string (not guaranteed to exist)
std::string maybe_dir = FUZZ_PARAM_STR();
const char *dir = ( ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u ) ? maybe_dir.c_str() : nullptr;
int r = s2n_config_set_verification_ca_location(config, file, dir);
(void) r;
// Validation: config remains valid; API may fail if sources are invalid which is allowed.

// Strictly parse and add a single PEM certificate
std::string pem = FUZZ_PARAM_STR();
int r = s2n_config_add_pem_to_trust_store(config, pem.c_str());
(void) r;
// Validation: config remains valid; errors are acceptable on malformed input.

// Clear all CAs from the trust store
int r = s2n_config_wipe_trust_store(config);
(void) r;
// Validation: config remains valid for further configuration.

// Attempt to load system certs; may fail if already loaded
int r = s2n_config_load_system_certs(config);
(void) r;
// Validation: config remains valid regardless of return value.

// Toggle verify-after-sign mode using a fuzzed enum value
s2n_verify_after_sign mode = ((*FUZZ_PARAM(unsigned int)) & 1u) ? S2N_VERIFY_AFTER_SIGN_ENABLED : S2N_VERIFY_AFTER_SIGN_DISABLED;
int r = s2n_config_set_verify_after_sign(config, mode);
(void) r;
// Validation: enum constrained to documented values; config remains valid.

// Size must be at least 1034. Constrain into [1034, 2048].
uint32_t size = (uint32_t)(*FUZZ_PARAM(unsigned int) % (2048u - 1034u + 1u)) + 1034u;
int r = s2n_config_set_send_buffer_size(config, size);
(void) r;
// Validation: respects minimum and keeps sizes small for fuzzing performance.

// Enable/disable multi-record recv behavior
bool enabled = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
int r = s2n_config_set_recv_multi_record(config, enabled);
(void) r;
// Validation: config remains valid; boolean constrained.

// Register a hostname verification callback; return 1 (trust) if non-empty hostname
s2n_verify_host_fn cb = +[](const char *host_name, size_t host_name_len, void *data) -> uint8_t {
    (void) data;
    if (host_name == nullptr) return 0;
    return (host_name_len > 0) ? 1 : 0;
};
void *ctx = (void *)(uintptr_t)(*FUZZ_PARAM(unsigned int));
int r = s2n_config_set_verify_host_callback(config, cb, ctx);
(void) r;
// Validation: callback follows contract (1 trust, 0 reject) and uses stable ctx pointer.

// Enable or disable OCSP response checking
uint8_t check = (uint8_t)((*FUZZ_PARAM(unsigned int)) & 1u);
int r = s2n_config_set_check_stapled_ocsp_response(config, check);
(void) r;
// Validation: value constrained to {0,1}; config remains valid.

// Disable X.509 validity time checks (testing only)
int r = s2n_config_disable_x509_time_verification(config);
(void) r;
// Validation: config remains valid; security implications are acceptable in fuzz context.

// Disable Key Usage / Extended Key Usage intent verification (testing only)
int r = s2n_config_disable_x509_intent_verification(config);
(void) r;
// Validation: config remains valid; used only to exercise API paths.

// Disable all X.509 verification for testing
int r = s2n_config_disable_x509_verification(config);
(void) r;
// Validation: config remains valid; dangerous in production but fine for fuzzing.

// max_depth must be >= 1. Choose in [1, 16] to keep small.
uint16_t max_depth = (uint16_t)((*FUZZ_PARAM(unsigned int)) % 16u) + 1u;
int r = s2n_config_set_max_cert_chain_depth(config, max_depth);
(void) r;
// Validation: parameter honors documented lower bound; config is returned for continued use.

// Provide a NUL-terminated PEM string for DH params
std::string dh_pem = FUZZ_PARAM_STR();
int r = s2n_config_add_dhparams(config, dh_pem.c_str());
(void) r;
// Validation: config remains valid; input is a NUL-terminated C string. Errors on malformed PEM are acceptable.

// Provide a policy name string; API will validate against supported names
std::string policy = FUZZ_PARAM_STR();
int r = s2n_config_set_cipher_preferences(config, policy.c_str());
