            return rng.randint(0, 39)
        else:
            # for first arc 2, allow a wide range including large values
            # mix small and large arcs to exercise base-128 boundaries
            if rng.random() < 0.5:
                return rng.randint(0, 200)
            # Large arc up to ~2^28 to produce multi-byte base-128 encodings
            return rng.randint(200, (1 << 28))
    # Subsequent arcs: biased mix of small/large
    p = rng.random()
    if p < 0.7:
        return rng.randint(0, 200)
    elif p < 0.9:
        return rng.randint(200, 100000)
    else:
        return rng.randint(100000, 1 << 28)


def _random_oid_bytes(rng: random.Random, target_len: int | None = None) -> bytes:
    # Build random arcs, then DER-encode and enforce max length 64 bytes.
    for _ in range(100):  # bounded attempts to hit size constraints
        first = _random_arc(rng, first=True)
        second = _random_arc(rng, second_for_first=first)
        arcs = [first, second]
        # Decide number of additional arcs
        extra = rng.randint(0, 10)
        for _i in range(extra):
            arcs.append(_random_arc(rng))
        encoded = _encode_oid(arcs)
        if target_len is not None:
            # Try to steer towards target length by adding/removing arcs
            if len(encoded) < target_len and len(encoded) < 64:
                # Add arcs until close to target_len or we hit size limit
                while len(encoded) < target_len and len(encoded) < 64:
                    arcs.append(_random_arc(rng))
                    encoded = _encode_oid(arcs)
            elif len(encoded) > target_len:
                # Trim arcs if possible (keep at least 2 arcs overall)
                while len(arcs) > 2:
                    arcs.pop()
                    enc2 = _encode_oid(arcs)
                    if len(enc2) <= target_len:
                        encoded = enc2
                        break
        if 1 <= len(encoded) <= 64:
            return encoded
    # Fallback to a simple, short valid OID
    return _encode_oid([1, 3, 6])


def _choose_strategy(rng: random.Random):
    # Weighted choice among strategies
    return rng.choices(
        ["catalog", "random_short", "random_medium", "random_near_limit", "catalog_mutate"],
        weights=[3, 3, 4, 2, 2],
    )[0]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    strategy = _choose_strategy(rng)

    if strategy == "catalog":
        oid = rng.choice(_COMMON_OIDS)
        encoded = _encode_oid(oid)
        # Ensure within cap (all catalog items are short)
        return encoded

    if strategy == "catalog_mutate":
        base = list(rng.choice(_COMMON_OIDS))
        # Mutate by appending 0-3 additional arcs, keeping it valid and within size
        for _ in range(rng.randint(0, 3)):
            base.append(_random_arc(rng))
        enc = _encode_oid(base)
        if len(enc) > 64:
            # Trim by removing arcs from end
            while len(base) > 2 and len(enc) > 64:
                base.pop()
                enc = _encode_oid(base)
        return enc if len(enc) >= 1 else _encode_oid([1, 3, 6])

    if strategy == "random_short":
        # Aim for 1..8 bytes
        target_len = rng.randint(1, 8)
        return _random_oid_bytes(rng, target_len)

    if strategy == "random_medium":
        # Aim for 9..24 bytes
        target_len = rng.randint(9, 24)
        return _random_oid_bytes(rng, target_len)

    if strategy == "random_near_limit":
        # Aim for 48..64 bytes to exercise boundary conditions
        target_len = rng.randint(48, 64)
        return _random_oid_bytes(rng, target_len)

    # Fallback
    return _encode_oid([1, 3, 6])
